app.use(express.text());

app.post('/decideUnsubscribe', (req, res) => {
    const emailContent = req.body;
    const unsubscribeKeywords = [
        "unsubscribe",
        "remove me",
        "deregister me",
        "stop sending me",
        "delete me"
    ];

    // Improved regex for extracting email address
