        const lowerCaseContent = emailContent.toLowerCase();
        unsubscribe = unsubscribeKeywords.some(keyword => lowerCaseContent.includes(keyword));
    }

    res.status(200).json({
        email: email,
        unsubscribe: unsubscribe
    });
});

app.listen(5000, '0.0.0.0', () => {
